// AVATR Dashcam — Cloudflare Worker "avt-cam" on cam.vmavt.com
// Serves the phone app (also used inside the Android APK), passes the car's clip lists
// through to the phone, and gives each car its own permanent address (cam-xxxx.vmavt.com).
//
// Bindings (Worker > Settings):
//   KV namespace : CARS            (any name, e.g. avt-cam)        — needed for car addresses
//   Secret       : CF_API_TOKEN    (Cloudflare API token: Account › Cloudflare Tunnel › Edit, Zone › DNS › Edit for vmavt.com)
//   Variable     : CF_ACCOUNT_ID   (your Cloudflare account id)
//   Variable     : CF_ZONE_ID      (zone id of vmavt.com)
//   Secret       : ENROLL_SECRET   (the long code from the setup notes — the AVT kit uses the same one)
//   Secret       : TG_TOKEN / Variable TG_CHAT   (optional Telegram alert when a car gets an address)
//   Variable     : ANDROID_CERT_SHA256 (optional, lets camera-scanned links open straight in the Android app)

const ASSETS_GZ = "";
let ASSETS = null;
async function assets() {
  if (ASSETS) return ASSETS;
  const bin = Uint8Array.from(atob(ASSETS_GZ), (c) => c.charCodeAt(0));
  const txt = await new Response(new Blob([bin]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
  ASSETS = JSON.parse(txt);
  return ASSETS;
}
const DOMAIN = "vmavt.com";

export default {
  async fetch(req, env, ctx) {
    const url = new URL(req.url);
    const p = url.pathname;
    try {
      if (p === "/" || p === "/add" || p === "/index.html") return page((await assets()).html);
      if (p === "/ping") return text("ok avt-cam");
      if (p === "/manifest.webmanifest") return manifest();
      if (p === "/sw.js") return new Response(SW, { headers: { "content-type": "text/javascript", "cache-control": "no-cache" } });
      if (p === "/jsqr.js") return jsqr(ctx);
      const ic = p.match(/^\/icon-(180|192|512)\.png$/);
      if (ic) return png((await assets()).icons[ic[1]]);
      if (p === "/api/proxy") return proxy(url, req);
      if (p === "/challenge") return challenge(env);
      if (p === "/enroll" && req.method === "POST") return enroll(req, env, url);
      if (p === "/.well-known/assetlinks.json") return assetlinks(env);
      return text("not found", 404);
    } catch (e) {
      return json({ message: "Server error: " + (e && e.message) }, 500);
    }
  },
};

// ---------- phone app ----------
function page(html) {
  return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
}
function manifest() {
  return json({
    name: "AVATR Dashcam", short_name: "Dashcam", start_url: "/", scope: "/", display: "standalone",
    background_color: "#0b0c0e", theme_color: "#0b0c0e",
    icons: [{ src: "/icon-192.png", sizes: "192x192", type: "image/png" }, { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" }],
  });
}
const SW = `self.addEventListener('install',e=>self.skipWaiting());self.addEventListener('activate',e=>self.clients.claim());self.addEventListener('fetch',()=>{});`;
function png(b64) {
  const bin = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  return new Response(bin, { headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" } });
}
async function jsqr(ctx) {
  const cache = caches.default, key = new Request("https://cam.vmavt.com/jsqr.js");
  let r = await cache.match(key);
  if (!r) {
    const up = await fetch("https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js");
    if (!up.ok) return text("// qr reader unavailable", 502);
    r = new Response(await up.text(), { headers: { "content-type": "text/javascript", "cache-control": "public, max-age=604800" } });
    ctx.waitUntil(cache.put(key, r.clone()));
  }
  return r;
}

// Clip lists are small JSON; the phone can't read them cross-site, so we pass them through.
// Only car addresses and only the read-only list endpoints are allowed.
const PROXY_PATHS = new Set(["/health", "/api/index", "/api/session", "/api/preview"]);
async function proxy(url, req) {
  let target;
  try { target = new URL(url.searchParams.get("u") || ""); } catch (_) { return json({ error: "bad url" }, 400); }
  const h = target.hostname;
  const okHost = /^cam-[a-z0-9-]+\.vmavt\.com$/.test(h) || /\.trycloudflare\.com$/.test(h);
  if (target.protocol !== "https:" || !okHost || !PROXY_PATHS.has(target.pathname)) return json({ error: "not allowed" }, 403);
  let r;
  try {
    r = await fetch(target.toString(), { headers: { "user-agent": "AVATR-Dashcam" }, cf: { cacheTtl: 0 } });
  } catch (_) {
    return json({ error: "car offline" }, 504);
  }
  if (r.status === 530 || r.status === 502 || r.status === 1033) return json({ error: "car offline" }, 504);
  return new Response(r.body, { status: r.status, headers: { "content-type": r.headers.get("content-type") || "application/json", "cache-control": "no-store" } });
}

// ---------- giving each car a permanent address ----------
async function hmacHex(secret, msg) {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(msg)));
  return [...sig].map((b) => b.toString(16).padStart(2, "0")).join("");
}
async function sha256Hex(s) {
  const d = new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s)));
  return [...d].map((b) => b.toString(16).padStart(2, "0")).join("");
}
async function challenge(env) {
  if (!env.ENROLL_SECRET) return json({ message: "Phone access isn't set up on the server yet." }, 503);
  const ts = Math.floor(Date.now() / 1000).toString();
  return json({ challenge: ts + "." + (await hmacHex(env.ENROLL_SECRET, "ch|" + ts)).slice(0, 32) });
}
async function enroll(req, env, url) {
  if (!env.ENROLL_SECRET || !env.CF_API_TOKEN || !env.CF_ACCOUNT_ID || !env.CF_ZONE_ID || !env.CARS)
    return json({ message: "Phone access isn't set up on the server yet." }, 503);
  let b; try { b = await req.json(); } catch (_) { return json({ message: "Bad request." }, 400); }
  const carId = String(b.carId || ""), ch = String(b.challenge || ""), mac = String(b.mac || "");
  if (!/^[0-9a-f]{32}$/.test(carId)) return json({ message: "This car's ID isn't valid." }, 400);
  const [ts, sig] = ch.split(".");
  const age = Math.floor(Date.now() / 1000) - parseInt(ts || "0", 10);
  if (!sig || age < 0 || age > 600 || sig !== (await hmacHex(env.ENROLL_SECRET, "ch|" + ts)).slice(0, 32))
    return json({ message: "The code expired — try again." }, 403);
  if (mac !== (await hmacHex(env.ENROLL_SECRET, carId + "|" + ch))) return json({ message: "This car isn't allowed to get an address." }, 403);

  const saved = await env.CARS.get("car:" + carId, "json");
  if (saved) return json(reply(saved));

  const slug = (await sha256Hex("avt-cam|" + carId)).slice(0, 12);
  const hostname = `cam-${slug}.${DOMAIN}`;
  const secretBytes = crypto.getRandomValues(new Uint8Array(32));
  const tunnelSecret = btoa(String.fromCharCode(...secretBytes));
  const api = (path, init) => fetch("https://api.cloudflare.com/client/v4" + path, {
    ...init, headers: { authorization: "Bearer " + env.CF_API_TOKEN, "content-type": "application/json" },
  }).then((r) => r.json());

  const t = await api(`/accounts/${env.CF_ACCOUNT_ID}/cfd_tunnel`, {
    method: "POST", body: JSON.stringify({ name: "avt-cam-" + slug, tunnel_secret: tunnelSecret, config_src: "local" }),
  });
  if (!t.success) return json({ message: "Cloudflare refused the new address: " + errs(t) }, 502);
  const tunnelId = t.result.id;

  const dns = await api(`/zones/${env.CF_ZONE_ID}/dns_records`, {
    method: "POST", body: JSON.stringify({ type: "CNAME", name: hostname, content: `${tunnelId}.cfargotunnel.com`, proxied: true, comment: "AVATR Dashcam car" }),
  });
  if (!dns.success) {
    // an old record for this car may exist — point it at the new tunnel
    const found = await api(`/zones/${env.CF_ZONE_ID}/dns_records?name=${hostname}`, { method: "GET" });
    const rec = found.success && found.result && found.result[0];
    if (!rec) return json({ message: "Cloudflare refused the DNS record: " + errs(dns) }, 502);
    const upd = await api(`/zones/${env.CF_ZONE_ID}/dns_records/${rec.id}`, {
      method: "PUT", body: JSON.stringify({ type: "CNAME", name: hostname, content: `${tunnelId}.cfargotunnel.com`, proxied: true, comment: "AVATR Dashcam car" }),
    });
    if (!upd.success) return json({ message: "Cloudflare refused the DNS record: " + errs(upd) }, 502);
  }
  const rec = { hostname, tunnelId, secret: tunnelSecret, account: env.CF_ACCOUNT_ID, at: Date.now() };
  await env.CARS.put("car:" + carId, JSON.stringify(rec));
  if (env.TG_TOKEN && env.TG_CHAT) {
    try {
      await fetch(`https://api.telegram.org/bot${env.TG_TOKEN}/sendMessage`, {
        method: "POST", headers: { "content-type": "application/json" },
        body: JSON.stringify({ chat_id: env.TG_CHAT, text: `📷 Car got a dashcam address\n${hostname}\ncar ${carId}` }),
      });
    } catch (_) {}
  }
  return json(reply(rec));
}
function reply(rec) {
  return { hostname: rec.hostname, tunnelId: rec.tunnelId, credentials: { AccountTag: rec.account, TunnelSecret: rec.secret, TunnelID: rec.tunnelId } };
}
function errs(r) { return ((r && r.errors) || []).map((e) => e.message).join("; ") || "unknown error"; }

function assetlinks(env) {
  const fp = (env.ANDROID_CERT_SHA256 || "").trim();
  return json(fp ? [{ relation: ["delegate_permission/common.handle_all_urls"], target: { namespace: "android_app", package_name: "com.avt.dashcam", sha256_cert_fingerprints: [fp] } }] : []);
}

// ---------- helpers ----------
function text(s, status = 200) { return new Response(s, { status, headers: { "content-type": "text/plain; charset=utf-8" } }); }
function json(o, status = 200) { return new Response(JSON.stringify(o), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } }); }
